import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {BusinessTeamHeaderView} from '../components/BusinessTeamHeaderView'
import {Blankslate} from '@primer/react/experimental'
import {ActionList, ActionMenu, Banner, Button, FormControl, Pagination, Spinner, Stack, TextInput} from '@primer/react'
import {
  OrganizationIcon,
  SearchIcon,
  XIcon,
  SortDescIcon,
  SortAscIcon,
  ListUnorderedIcon,
  TypographyIcon,
} from '@primer/octicons-react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {ListView} from '@github-ui/list-view'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemLeadingContent} from '@github-ui/list-view/ListItemLeadingContent'
import {ListItemLeadingVisual} from '@github-ui/list-view/ListItemLeadingVisual'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListViewDensityToggle} from '@github-ui/list-view/ListViewDensityToggle'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import type {EnterpriseTeam, Organization} from '../types'
import pluralize from 'pluralize'
import styles from '../styles/BusinessTeamOrganizationsView.module.css'
import {useState} from 'react'
import {ListItemActionBar} from '@github-ui/list-view/ListItemActionBar'
import type {SafeHTMLString} from '@github-ui/safe-html'
import {VerifiedHTMLBox} from '@github-ui/safe-html/VerifiedHTML'
import OrganizationDeleteDialog from '../components/OrganizationDeleteDialog'
import {handleOrgDelete} from '../helpers/HandleOrgDelete'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {pathingForTeam} from '../paths'
import {OrganizationSelectPanel} from '../helpers/OrganizationSelectPanel'
import {updateSearchParams} from '@github-ui/history'
import {useDebounce} from '@github-ui/use-debounce'

export interface BusinessTeamOrganizationsViewPayload {
  orgAssignmentsEnabled: boolean
  isEnterpriseSecurityManager: boolean
  enterpriseTeamsOrgAssignmentLimit: number
  viewerPermissions: {[permission: string]: boolean}
  enterpriseSlug: string
  enterpriseTeam: EnterpriseTeam
  organizations?: Organization[]
  meta: {
    pageSize: number
    page: number
    queryOrgCount: number
    sortOption: string
    orderOption: string
  }
}

export function BusinessTeamOrganizationsView() {
  const payload = useRoutePayload<BusinessTeamOrganizationsViewPayload>()
  const [organizationSelectionType, setOrganizationSelectionType] = useState(
    payload.enterpriseTeam.organizationSelectionType,
  )
  const [orgs, setOrgs] = useState<Organization[]>(payload.organizations || [])
  const [variant, setVariant] = useState<'default' | 'compact'>(() => {
    if (typeof window === 'undefined') return 'default'
    const stored = localStorage.getItem('list-view-density')
    return stored === '1' ? 'compact' : 'default'
  })
  const [totalOrgCount, setTotalOrgCount] = useState(payload.meta.queryOrgCount || 0)
  const {enterpriseTeam, ...restPayload} = payload
  const [flash, setFlash] = useState<SafeHTMLString>('' as SafeHTMLString)
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const [selectedOrgs, setSelectedOrgs] = useState<Organization[]>([])
  const [searchParams, setSearchParams] = useState(
    () => new URLSearchParams(typeof window !== `undefined` ? window.location.search : ''),
  )
  const [metaData, setMetaData] = useState(payload.meta)
  const [currentPage, setCurrentPage] = useState(payload.meta.page)
  const navPathing = pathingForTeam(payload.enterpriseSlug, payload.enterpriseTeam.slug)

  const sortOption = metaData.sortOption
  const orderOption = metaData.orderOption

  const [loading, setLoading] = useState(false)
  const [searchQuery, setSearchQuery] = useState(searchParams.get('query') || '')
  //This is for orgs header count which is separate from totalOrgCount used for listing
  const [teamOrgCount, setTeamOrgCount] = useState(payload.enterpriseTeam.totalOrganizationCount)

  // Only update totalOrganizationCount when organizations are actually added/removed, not during search
  const updatedTeam = {
    ...enterpriseTeam,
    totalOrganizationCount: teamOrgCount,
  }

  const handleDeleteConfirmation = async () => {
    const response = await handleOrgDelete(payload.enterpriseSlug, payload.enterpriseTeam.slug, selectedOrgs, setFlash)
    setIsDeleteDialogOpen(false)

    if (response && response.message) {
      // Update team org count when organizations are actually removed
      setTeamOrgCount(prev => prev - selectedOrgs.length)
      paginate(1)
    }
  }

  const setSearchParam = (key: string, value: string) => {
    if (value === '') {
      searchParams.delete(key)
    } else {
      searchParams.set(key, value)
    }
    setSearchParams(searchParams)
    updateSearchParams(searchParams)
  }

  const paginate = async (page: number): Promise<void> => {
    setSearchParam('page', page.toString())
    const result = await verifiedFetchJSON(`${navPathing.base}/organizations?${searchParams.toString()}`, {
      method: 'GET',
      headers: {Accept: 'application/json'},
    })
    const data = (await result.json()).payload as BusinessTeamOrganizationsViewPayload

    setCurrentPage(page)
    setOrgs(data?.organizations || [])
    setTotalOrgCount(data?.meta?.queryOrgCount || 0)
    // Always update team org count when we get fresh data and not searching
    // This ensures header count is updated when orgs are added/removed
    if (!searchQuery && data?.enterpriseTeam?.totalOrganizationCount !== undefined) {
      setTeamOrgCount(data.enterpriseTeam.totalOrganizationCount)
    }
    setLoading(false)
    if (data?.meta) {
      setMetaData(data.meta)
    }
  }

  const handleSortChange = (newSortOption: string) => {
    setSearchParam('sort', newSortOption)
    paginate(1)
  }

  const handleSearch = (searchValue: string) => {
    setSearchQuery(searchValue)
    setLoading(true)
    debounceFetchSearchData(searchValue)
  }

  const debounceFetchSearchData = useDebounce((nextValue: string) => {
    setSearchParam('query', nextValue)
    paginate(1)
  }, 300)

  const handleSortOrderChange = (newOrderOption: string) => {
    setSearchParam('order', newOrderOption)
    paginate(1)
  }

  const handlePageChange = (newPage: number) => {
    setLoading(true)
    paginate(newPage)
  }

  const handleDensityChange = (density: number) => {
    setVariant(density === 1 ? 'compact' : 'default')
  }

  const showBlankSlate =
    organizationSelectionType === 'all' ||
    organizationSelectionType === 'disabled' ||
    (organizationSelectionType === 'selected' && totalOrgCount === 0 && !searchQuery && !loading)

  function handleAddOrganizations() {
    paginate(1)
    if (organizationSelectionType === 'disabled') {
      setOrganizationSelectionType('selected')
    }
  }

  const orgLimitReachedMessage = `Your team has reached the ${
    payload.enterpriseTeamsOrgAssignmentLimit
  } organization limit. ${
    payload.isEnterpriseSecurityManager
      ? `You can’t modify the organization list while the Enterprise Security Manager role is assigned.`
      : `Remove existing organizations to add more.`
  }`

  return (
    <>
      {flash && (
        <Banner
          hideTitle
          title="error"
          data-testid="flash-error"
          variant="critical"
          className="mb-3"
          secondaryAction={
            <Button variant="invisible" onClick={() => setFlash('' as SafeHTMLString)}>
              <XIcon />
            </Button>
          }
        >
          <VerifiedHTMLBox html={flash} />
        </Banner>
      )}

      <BusinessTeamHeaderView {...restPayload} enterpriseTeam={updatedTeam} currentView="Organizations" />

      {showBlankSlate ? (
        <Blankslate spacious>
          <Blankslate.Visual>
            <OrganizationIcon size={24} className="color-fg-muted mb-2" />
          </Blankslate.Visual>
          {organizationSelectionType === 'all' ? (
            <>
              <Blankslate.Heading>
                Your team has access to all organizations in {payload.enterpriseSlug}.
              </Blankslate.Heading>
              <Blankslate.Description>
                Your team currently has access to all {teamOrgCount} organizations. To limit access to specific
                organizations, update the team access in the settings page.
              </Blankslate.Description>
              <Button
                className="mt-4"
                as="a"
                href={`/enterprises/${payload.enterpriseSlug}/teams/${payload.enterpriseTeam.slug}/edit`}
              >
                Update settings
              </Button>
              <Blankslate.SecondaryAction href={`/enterprises/${payload.enterpriseSlug}/organizations`}>
                See all organizations
              </Blankslate.SecondaryAction>
            </>
          ) : (
            <>
              <Blankslate.Heading>Your team doesn&apos;t have access to any organizations.</Blankslate.Heading>
              <Blankslate.Description>
                Use the &apos;Add organizations&apos; button below to add organizations to your team.
              </Blankslate.Description>
              <div className="d-flex justify-center align-items-center mt-4">
                <OrganizationSelectPanel
                  enterpriseSlug={payload.enterpriseSlug}
                  alreadyAssignedOrgCount={totalOrgCount}
                  initialSelectedIds={[]}
                  onOrganizationsAdded={handleAddOrganizations}
                  enterpriseTeamsOrgAssignmentLimit={payload.enterpriseTeamsOrgAssignmentLimit}
                  teamSlug={payload.enterpriseTeam.slug}
                />
              </div>
              <Blankslate.SecondaryAction
                href={`/enterprises/${payload.enterpriseSlug}/teams/${payload.enterpriseTeam.slug}/edit`}
              >
                Update settings
              </Blankslate.SecondaryAction>
            </>
          )}
        </Blankslate>
      ) : (
        <>
          <div className="mt-3 mb-3">
            <Stack direction="horizontal" justify="space-between">
              <FormControl>
                <FormControl.Label visuallyHidden>Organization Search</FormControl.Label>
                <TextInput
                  className={styles.organizationSearchInput}
                  leadingVisual={loading ? <Spinner size="small" className="mt-1" /> : SearchIcon}
                  placeholder="Find an organization..."
                  value={searchQuery}
                  onChange={e => handleSearch(e.target.value)}
                  data-testid="organization-search-input"
                />
              </FormControl>
              <OrganizationSelectPanel
                enterpriseSlug={payload.enterpriseSlug}
                alreadyAssignedOrgCount={totalOrgCount}
                initialSelectedIds={[]}
                onOrganizationsAdded={handleAddOrganizations}
                enterpriseTeamsOrgAssignmentLimit={payload.enterpriseTeamsOrgAssignmentLimit}
                teamSlug={payload.enterpriseTeam.slug}
              />
            </Stack>
          </div>

          <div className="mt-3">
            <ListView
              title="Organizations"
              variant={variant}
              itemsListClassName={styles.organizationListView}
              metadata={
                <ListViewMetadata
                  title={`${totalOrgCount} ${pluralize('organization', totalOrgCount)}`}
                  className={`${styles.organizationListViewMetadata} ${orgs.length === 0 ? styles.noBottomBorder : ''}`}
                  densityToggle={<ListViewDensityToggle onChange={handleDensityChange} className="mr-2" />}
                >
                  {
                    <div className="d-flex flex-justify-end flex-items-center">
                      <ActionMenu>
                        <ActionMenu.Button className={styles.sortMenuButton} data-testid="filterDropdown-header">
                          {orderOption === 'Descending' ? (
                            <SortDescIcon size={16} className="mr-1" />
                          ) : (
                            <SortAscIcon size={16} className="mr-1" />
                          )}
                          {sortOption}
                        </ActionMenu.Button>
                        <ActionMenu.Overlay>
                          <ActionList selectionVariant="single">
                            <ActionList.Item
                              data-testid="sort-last-added"
                              selected={sortOption === 'Last added'}
                              onSelect={() => handleSortChange('Last added')}
                            >
                              <ListUnorderedIcon size={16} className="mr-2" />
                              Last added
                            </ActionList.Item>
                            <ActionList.Item
                              data-testid="sort-name"
                              selected={sortOption === 'Name'}
                              onSelect={() => handleSortChange('Name')}
                            >
                              <TypographyIcon size={16} className="mr-2" />
                              Name
                            </ActionList.Item>
                            <ActionList.Divider />
                            <ActionList.Item
                              data-testid="sort-ascending"
                              selected={orderOption === 'Ascending'}
                              onSelect={() => handleSortOrderChange('Ascending')}
                            >
                              <SortAscIcon size={16} className="mr-2" />
                              Ascending
                            </ActionList.Item>
                            <ActionList.Item
                              data-testid="sort-descending"
                              selected={orderOption === 'Descending'}
                              onSelect={() => handleSortOrderChange('Descending')}
                            >
                              <SortDescIcon size={16} className="mr-2" />
                              Descending
                            </ActionList.Item>
                          </ActionList>
                        </ActionMenu.Overlay>
                      </ActionMenu>
                    </div>
                  }
                </ListViewMetadata>
              }
            >
              {totalOrgCount >= payload.enterpriseTeamsOrgAssignmentLimit && (
                <Banner
                  title="Info"
                  hideTitle
                  description={orgLimitReachedMessage}
                  variant="info"
                  style={{
                    borderRadius: '0px',
                    borderTop: 'none',
                    borderLeft: 'none',
                    borderRight: 'none',
                  }}
                />
              )}
              {orgs.map(org => {
                const avatarSize = variant === 'compact' ? 20 : 28
                return (
                  <ListItem
                    key={org.id}
                    alignment="center"
                    data-testid={`list-item-${org.id}`}
                    className={!org.description ? styles.centerAvatar : undefined}
                    title={
                      <ListItemTitle
                        value={org.name || org.login}
                        headingClassName={styles.organizationListViewTitle}
                        href={`/${org.login}`}
                      />
                    }
                    secondaryActions={
                      <ListItemActionBar
                        label="organization actions"
                        staticMenuActions={[
                          {
                            key: 'remove-org',
                            render: () => {
                              return (
                                <ActionList.Item
                                  variant="danger"
                                  onSelect={() => {
                                    setFlash('' as SafeHTMLString)
                                    setSelectedOrgs([org])
                                    setIsDeleteDialogOpen(true)
                                  }}
                                  data-testid={`remove-org-${org.id}`}
                                  disabled={payload.isEnterpriseSecurityManager}
                                >
                                  <ActionList.LeadingVisual>
                                    <XIcon />
                                  </ActionList.LeadingVisual>
                                  Remove
                                </ActionList.Item>
                              )
                            },
                          },
                        ]}
                      />
                    }
                  >
                    <ListItemLeadingContent>
                      <ListItemLeadingVisual size={avatarSize}>
                        <GitHubAvatar square size={avatarSize} src={org.avatarUrl} alt="Organization avatar" />
                      </ListItemLeadingVisual>
                    </ListItemLeadingContent>
                    {org.description && (
                      <ListItemMainContent>
                        <ListItemDescription className={`text-small ${styles.secondaryTextColor}`}>
                          {org.description}
                        </ListItemDescription>
                      </ListItemMainContent>
                    )}
                  </ListItem>
                )
              })}
              {orgs.length === 0 && (
                <Blankslate spacious>
                  <Blankslate.Visual>
                    <SearchIcon size={24} className="color-fg-muted mb-2" />
                  </Blankslate.Visual>
                  <Blankslate.Heading>We couldn&apos;t find any matching organizations</Blankslate.Heading>
                  <Blankslate.Description>
                    No organization match your search criteria. Adjust your search or clear the filter to view all
                    organizations.
                  </Blankslate.Description>
                </Blankslate>
              )}
            </ListView>
            {totalOrgCount > payload.meta.pageSize && (
              <Pagination
                data-testid="pagination"
                pageCount={Math.ceil(totalOrgCount / payload.meta.pageSize)}
                currentPage={currentPage}
                onPageChange={(_, newPage) => handlePageChange(newPage)}
                showPages={{
                  narrow: true,
                }}
              />
            )}
          </div>
          <OrganizationDeleteDialog
            isOpen={isDeleteDialogOpen}
            onClose={() => setIsDeleteDialogOpen(false)}
            onConfirm={handleDeleteConfirmation}
            teamName={payload.enterpriseTeam.name}
            selectedOrganizations={selectedOrgs}
          />
        </>
      )}
    </>
  )
}

try{ BusinessTeamOrganizationsView.displayName ||= 'BusinessTeamOrganizationsView' } catch {}